:root {
  /* Colors */
  --color-fog-canvas: #f2f2f2;
  --color-paper-white: #ffffff;
  --color-frosted-glass: #ffffff66;
  --color-onyx-ink: #1c1d21;
  --color-jet-ink: #111111;
  --color-ink-caption: #111111a3;
  --color-iron-text: #6b7079;
  --color-slate-caption: #8a8f98;
  --color-steel-border: #d3dce6;
  --color-quartz-hairline: #e1e7ee;
  --color-signal-cobalt: #2563eb;
  --color-frost-blue: #e1effe;
  --color-iris-studio: #7c3aed;

  /* Typography — Font Families */
  --font-instrument-sans: "Instrument Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-source-serif-4: "Source Serif 4", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-geist: "Geist", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 10.5px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.5;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: -0.14px;
  --text-body: 15px;
  --leading-body: 1.55;
  --tracking-body: 0px;
  --text-body-lg: 19px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: -0.19px;
  --text-subheading: 21px;
  --leading-subheading: 1.5;
  --tracking-subheading: -0.42px;
  --text-heading: 48px;
  --leading-heading: 1;
  --tracking-heading: -1.44px;
  --text-heading-lg: 54px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -1.62px;
  --text-display: 60px;
  --leading-display: 0.98;
  --tracking-display: -1.8px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-56: 56px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-112: 112px;
  --spacing-128: 128px;

  /* Layout */
  --layout-max-width: 1120px;
  --layout-text-width: 760px;
  --layout-lead-width: 560px;
  --layout-section-gap: 128px;
  --layout-section-gap-mobile: 64px;
  --layout-card-padding: 24px;
  --layout-element-gap: 12px;
  --layout-nav-height: 76px;
  --layout-hero-inset: 32px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 6px;
  --radius-md-2: 8px;
  --radius-lg: 10px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-3xl: 28px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-pills: 9999px;
  --radius-badges: 9999px;
  --radius-avatars: 9999px;
  --radius-buttons: 10px;
  --radius-cards: 12px;
  --radius-sections: 28px;
  --radius-images: 16px;
  --radius-innerTiles: 8px;
  --radius-nav: 6px;
  --radius-smallElements: 2px;

  /* Shadows */
  --shadow-subtle: inset 0 0 0 1px rgba(17, 17, 17, 0.05);
  --shadow-subtle-2: inset 0 1px 0 0 rgba(255, 255, 255, 0.35), inset 0 -1px 0 0 rgba(0, 0, 0, 0.12);
  --shadow-sm: 0 0 0 1px rgba(17, 17, 17, 0.06), 0 1px 2px 0 rgba(17, 17, 17, 0.03);
  --shadow-sm-2: 0 1px 2px 0 rgba(0, 0, 0, 0.12);
  --shadow-md: 0 0 0 1px rgba(17, 17, 17, 0.06), 0 1px 2px 0 rgba(17, 17, 17, 0.03), 0 30px 60px -40px rgba(17, 24, 39, 0.25);
  --shadow-lg: inset 0 0 0 1px rgba(63, 127, 205, 0.65), inset 0 2px 3px -1px rgba(255, 255, 255, 0.8), inset 0 -1px 1px 0 rgba(61, 119, 194, 0.2), 0 1px 2px 0 rgba(61, 119, 194, 0.2), 0 10px 24px -10px rgba(120, 178, 240, 0.55);

  /* Surfaces */
  --surface-fog-canvas: #f2f2f2;
  --surface-paper-white: #ffffff;
  --surface-frost-blue: #e1effe;
  --surface-frosted-glass: #ffffff66;
  --surface-onyx-ink: #1c1d21;
}

